import React, { useState } from 'react';

const ChampionsLeagueHeader = ({ players, onTeamsClick, onSeasonsClick }) => {
  const [selectedSection, setSelectedSection] = useState(null);

  const handleSectionClick = (section) => {
    setSelectedSection(section === selectedSection ? null : section);
  };

  return (
    <header className="bg-champions-blue p-4 flex justify-between items-center shadow-md relative">
      {/* Logo y título principal */}
      <div className="flex items-center">
        <div className="w-16 h-16 mr-2 overflow-hidden rounded-lg shadow-lg border border-champions-gold/30">
          <img 
            src="/images/logos/cc.png" 
            alt="Champions League Logo" 
            className="w-full h-full object-contain transform hover:scale-105 transition-transform duration-300"
          />
        </div>
        <div className="ml-4">
          <h2 className="text-white font-bold text-xl">UEFA Champions League</h2>
          <p className="text-blue-300 text-sm">Estadísticas Históricas</p>
        </div>
      </div>

      {/* Navegación */}
      <nav className="hidden md:flex space-x-6">
        <a href="#" className="text-white hover:text-champions-gold transition-colors">
          Inicio
        </a>
        <button 
          className={`text-white hover:text-champions-gold transition-colors focus:outline-none ${selectedSection === 'teams' ? 'text-champions-gold' : ''}`}
          onClick={() => handleSectionClick('teams')}
        >
          Equipos
        </button>
        <button 
          className={`text-white hover:text-champions-gold transition-colors focus:outline-none ${selectedSection === 'seasons' ? 'text-champions-gold' : ''}`}
          onClick={() => handleSectionClick('seasons')}
        >
          Temporadas
        </button>
      </nav>

      {/* Trofeo decorativo */}
      <div className="hidden md:flex items-center">
        <div className="w-16 h-16 overflow-hidden">
          <img 
            src="/images/trophy.png" 
            alt="Champions Trophy" 
            className="w-full h-full object-contain animate-pulse"
          />
        </div>
      </div>
    </header>
  );
};

export default ChampionsLeagueHeader;
